        // No special setup needed - we'll interact directly with the deployed contract
        attackContract = new AttackContract();
        // Label for debugging
        vm.label(address(attackContract), "AttackContract");
        vm.label(TARGET, "HELL Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
